let checklistFilter='all';
function filterChecklist(value){checklistFilter=value;renderChecklist();document.querySelector(`[data-check-filter="${value}"]`)?.focus({preventScroll:true})}
function renderChecklist(){
 const pending=state.items.filter(i=>!i.checked),done=state.items.filter(i=>i.checked),percent=state.items.length?Math.round(done.length/state.items.length*100):0;
 const row=i=>`<div class="todo-row ${i.checked?'is-done':''}"><label class="todo-target" for="check-${i.id}"><input id="check-${i.id}" type="checkbox" ${i.checked?'checked':''} onchange="toggle('${i.id}')"><span class="todo-circle" aria-hidden="true"><svg viewBox="0 0 20 20" fill="none"><path d="m5 10 3 3 7-7" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span class="todo-copy"><b>${esc(i.name)}</b><small>${i.qty} ${esc(i.unit)} × ${money(i.price)}</small></span><span class="todo-price">${money(i.qty*i.price)}</span></label><button class="todo-remove" aria-label="Remover ${esc(i.name)}" onclick="removeItem('${i.id}')">×</button></div>`;
 const group=(title,items)=>items.length?`<div class="todo-group"><h3>${title}<span>${items.length}</span></h3>${items.map(row).join('')}</div>`:'';
 const filters=[['all','Todos',state.items.length],['pending','Faltam',pending.length],['done','No carrinho',done.length]];
 $('items').innerHTML=`<div class="todo-heading"><div><h2>Minha checklist</h2><p>Toque no produto quando colocar no carrinho.</p></div><span class="todo-percent">${percent}%</span></div><div class="todo-progress" role="progressbar" aria-label="Itens no carrinho" aria-valuemin="0" aria-valuemax="${state.items.length||1}" aria-valuenow="${done.length}"><span style="width:${percent}%"></span></div><p class="todo-status" role="status">${state.items.length?(pending.length?`${done.length} de ${state.items.length} itens no carrinho · faltam ${pending.length}`:'Tudo no carrinho! Sua lista está completa.'):'Sua lista está pronta para começar.'}</p><div class="todo-filters" aria-label="Filtrar checklist">${filters.map(([value,label,count])=>`<button type="button" data-check-filter="${value}" aria-pressed="${checklistFilter===value}" onclick="filterChecklist('${value}')">${label}<span>${count}</span></button>`).join('')}</div>${!state.items.length?'<div class="empty"><div class="todo-empty-symbol">✓</div><h2>O que falta em casa?</h2>Adicione os produtos acima e vá ticando durante a compra.</div>':`${checklistFilter!=='done'?group('Falta pegar',pending):''}${checklistFilter!=='pending'?group('Já no carrinho',done):''}${checklistFilter==='pending'&&!pending.length?'<div class="empty">✓ Tudo marcado! Você já pegou todos os produtos.</div>':''}${checklistFilter==='done'&&!done.length?'<div class="empty">Os produtos que você marcar aparecerão aqui.</div>':''}`}`;
}
